beforeExample:
interface IServiceLocator {
    <T> T getService(Class<T> api);
}

class MockWorkbench {
    public IServiceLocator getServiceLocator() {
        return new IServiceLocator() {
            @Override
            public <T> T getService(Class<T> api) {
                if (api.equals(MockEvaluationService.class)) {
                    return (T) new MockEvaluationService();
                }
                return null;
            }
        };
    }
}

class MockEvaluationService {
    public String evaluate() { return "evaluated"; }
}

public class MyClient {
    public void clientMethod() {
        IServiceLocator locator = new MockWorkbench().getServiceLocator();
        MockEvaluationService service = (MockEvaluationService) locator.getService(MockEvaluationService.class);
        service.evaluate();
    }
}

