    public IServiceLocatorOld getServiceLocator() {
        return new IServiceLocatorOld() {
            @Override
            public Object getService(Class<?> api) {
                if (api.equals(MockEvaluationService.class)) {
                    return new MockEvaluationService();
                }
                return null;
            }
        };
    }
}

class MockEvaluationService {
    public String evaluate() { return "evaluated"; }
}

public class MyClient {
    public void clientMethod() {
        IServiceLocatorOld locator = new MockWorkbenchOld().getServiceLocator();
        // This cast is necessary and should NOT be removed by the rule if getService() returns Object
        MockEvaluationService service = (MockEvaluationService) locator.getService(MockEvaluationService.class);
        service.evaluate();
    }
}

